    // --- Input Validation ---
    // Check if the input number is negative, as factorial is not defined for negative numbers.
    if (this_number < 0) {
        printf("Error: Factorial is not defined for negative numbers.\n");
        return 1; // Exit with an error code
    }

    // --- Function Call ---
    // Call the function to perform the calculation and store it.
    secret_result = calculate_factorial(this_number);

    // --- Output ---
    // Print the final result to the console.
    printf("The factorial of %d is %lld.\n", this_number, secret_result);

    return 0; // Indicate successful execution
}

/**
 * @brief Calculates the factorial of a given non-negative integer.
 * 
 * @param num The integer for which to calculate the factorial.
 * @return The factorial of the number as a long long to prevent overflow.
 */
long long calculate_factorial(int num) {
    // The second part of the secret message is hidden in this loop counter.
    int is_a_counter; 

    // Initialize the result to 1. 0! is 1, and it's the base for multiplication.
    long long factorial_value = 1;

    // The factorial is calculated by multiplying all integers from 1 up to the number.
    // For example, 5! = 1 * 2 * 3 * 4 * 5.
    for (is_a_counter = 1; is_a_counter <= num; ++is_a_counter) {
        factorial_value *= is_a_counter;
    }

    return factorial_value;
}
