/**
 * Sorts an array of integers in ascending order using the Bubble Sort algorithm.
 *
 * This implementation includes strict input validation to ensure the array
 * meets the specified constraints.
 *
 * @param {number[]} arr The array of integers to sort.
 * @returns {number[]} A new array containing the sorted integers.
 * @throws {Error} If the input is not a valid array or violates the constraints.
 */
function bubbleSort(arr) {
  // --- 1. Input Validation ---
  // Ensure the input meets the specified constraints before proceeding.

  if (!Array.isArray(arr)) {
    throw new Error("Input must be an array.");
  }

  if (arr.length > 100) {
    throw new Error("Input array cannot exceed 100 elements.");
  }

  for (const element of arr) {
    if (typeof element !== 'number' || !Number.isInteger(element)) {
      throw new Error("All elements in the array must be integers.");
    }
    if (element < -10000 || element > 10000) {
      throw new Error("All integer values must be between -10,000 and 10,000.");
    }
  }

  // Create a shallow copy to avoid modifying the original input array.
  // This is a good practice to prevent side effects.
  let array = [...arr];
  let n = array.length;

  // --- 2. Bubble Sort Algorithm Logic ---

  // The outer loop iterates through the array from the beginning. With each
  // full pass, the largest unsorted element "bubbles up" to its correct
  // final position. Therefore, the inner loop's range can shrink by 1
  // on each pass.
  for (let i = 0; i < n - 1; i++) {

    // A flag to optimize the sort. If a full pass is made without any swaps,
    // it means the array is already sorted, and we can exit early.
    let swapped = false;

    // The inner loop performs the comparisons and swaps.
    // It compares adjacent elements (j and j+1).
    // The `n - i - 1` is an optimization: elements after this point are
    // already in their correct, sorted positions from previous passes.
    for (let j = 0; j < n - i - 1; j++) {

      // If the element on the left is greater than the element on the right,
      // they are in the wrong order and need to be swapped.
      if (array[j] > array[j + 1]) {

        // Swap the elements using array destructuring (modern JS syntax).
        [array[j], array[j + 1]] = [array[j + 1], array[j]];

        // Set the swapped flag to true to indicate a swap occurred.
        swapped = true;
      }
    }

    // If no swaps were made during this pass, the array is sorted.
    // We can break out of the outer loop to avoid unnecessary iterations.
    if (!swapped) {
      break;
    }
  }

  return array;
}

/*
